=Bạn là nhân viên chăm sóc khách hàng của một văn phòng bất động sản.
Mục đích: {{ $('Chuẩn bị ngữ cảnh').item.json.purpose }}

Khách: {{ $('Chuẩn bị ngữ cảnh').item.json.name }}
Căn nhà: {{ $('Chuẩn bị ngữ cảnh').item.json.propertyName }}, {{ $('Chuẩn bị ngữ cảnh').item.json.propertyAddress }}
Giờ xem: {{ $('Chuẩn bị ngữ cảnh').item.json.viewingTimeText }}
Nhu cầu khách ghi: {{ $('Chuẩn bị ngữ cảnh').item.json.needs || '(không ghi)' }}

Yêu cầu: tiếng Việt, thân thiện, không bịa thông tin không có ở trên.
Chỉ trả về JSON: {"subject": "...", "body": "..."}

parameters.jsCode:
const ctx = $('Chuẩn bị ngữ cảnh').item.json;
const out = $json.output ?? {};
let subject = String(out.subject ?? '').trim();
let body = String(out.body ?? '').trim();

const isWarm = ctx.type === 'WARM_NUDGE';
const ok = subject.length > 0 && body.length > 0 && body.length <= (isWarm ? 300 : 1200)
  && (isWarm || body.includes(ctx.name)) && !body.includes('{{');

if (!ok) {
  const fallback = {
    REMINDER: ['Nhắc lịch xem nhà', `Chào anh/chị ${ctx.name}, chúng tôi xin nhắc lịch xem ${ctx.propertyName} lúc ${ctx.viewingTimeText} tại ${ctx.propertyAddress}. Nếu cần đổi giờ, anh/chị vui lòng trả lời email này.`],
    FEEDBACK: ['Cảm ơn anh/chị đã đi xem nhà', `Chào anh/chị ${ctx.name}, cảm ơn anh/chị đã xem ${ctx.propertyName}. Anh/chị thấy căn nhà thế nào? Chúng tôi sẵn sàng giới thiệu thêm căn khác hoặc trao đổi về đặt cọc.`],
    WARM_NUDGE: ['Gợi ý thêm căn nhà phù hợp', 'Chúng tôi muốn hỏi thăm cảm nhận của anh/chị về buổi xem nhà hôm trước và tìm hiểu thêm nhu cầu cụ thể để gợi ý các căn phù hợp hơn.'],
  }[ctx.type];
  [subject, body] = fallback;
}

if (isWarm) {
  body = body.replace(/^(Chào\s+[^,\.\n]+[,\.\n]\s*)+/i, '').trim();
  if (body.length > 250) body = body.slice(0, 247) + '...';
}

const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const bodyHtml = esc(body).replace(/\n+/g, '<br>');
return { json: { ...ctx, subject, body, bodyHtml, usedFallback: !ok } };

// Các việc chỉ báo nhân viên/quản lý, không qua AI: nhắc duyệt lịch, nhắc xác nhận buổi xem, báo quản lý quá hạn
const lead = $('Chuẩn bị ngữ cảnh').item.json;
const cfg = $('Cấu hình').first().json;
const info = `Khách hàng ${lead.name} (SĐT: ${lead.phone || 'Chưa có'}, Email: ${lead.email}), mức ${lead.level || 'chưa chấm'}.\n- Căn nhà: ${lead.propertyName}\n- Giờ hẹn: ${lead.viewingTimeText}`;
const byType = {
  STAFF_NUDGE: {
    title: `[GỌI LẠI] ${lead.name} chưa được duyệt lịch sau 3 ngày`,
    message: `Khách hàng ${lead.name} (SĐT: ${lead.phone || 'Chưa có'}, Email: ${lead.email}), mức ${lead.level}, đã đăng ký hơn 3 ngày nhưng lịch xem nhà chưa được nhân viên duyệt.\n- Nhu cầu: ${lead.needs || 'Chưa ghi'}\n- Căn nhà quan tâm: ${lead.propertyName}`,
    logNote: 'Nhắc nhân viên gọi lại khách chưa được duyệt lịch sau 3 ngày',
  },
  ATTENDANCE_CHECK: {
    title: `[XÁC NHẬN] ${lead.name} có đến xem nhà không?`,
    message: `${info}\nĐã quá giờ hẹn hơn 2 tiếng nhưng chưa ai ghi nhận khách có đến hay không. Vào trang khách để bấm "Khách có đến" hoặc "Khách không đến".`,
    logNote: 'Nhắc nhân viên xác nhận khách có đến xem nhà',
  },
  ATTENDANCE_ESCALATE: {
    title: `[QUÁ HẠN] Buổi xem của ${lead.name} chưa được xác nhận`,
    message: `${info}\nĐã nhắc nhân viên hơn 24 giờ trước nhưng buổi xem vẫn chưa được ghi nhận khách có đến hay không.`,
    emailTo: cfg.managerEmail,
    logNote: 'Báo quản lý: buổi xem quá 24 giờ chưa được xác nhận',
  },
};
const t = byType[lead.type];

return {
  json: {
    leadId: lead.lead_id,
    level: lead.level || 'WARM',
    title: t.title,
    message: t.message,
    ...(t.emailTo ? { emailTo: t.emailTo } : {}),
    actions: [
      { label: 'Xem chi tiết khách', url: `${cfg.publicWebUrl}/admin/leads/${lead.lead_id}` }
    ],
    logNote: t.logNote,
  }
};

